import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({ baseDirectory: __dirname });

const eslintConfig = [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    /* `next-env.d.ts` is generated by Next on every dev/build, is gitignored, and
     * carries a "should not be edited" banner — yet `next/typescript` flags its
     * triple-slash references. Linting a file we are not allowed to fix can only
     * ever fail the gate. */
    ignores: [".next/**", "out/**", "node_modules/**", "next-env.d.ts"],
  },
];

export default eslintConfig;
